export function parseAndNormalizeSpell(spell, options={
    isItem: false,
    variantIndex: 0
}) {

    const { isItem=false, variantIndex=0 } = options
    let spellModified = {...spell}
    
    // Normalize Name
    spellModified.Name = getNormalizedSpellName(spell)
    spellModified.IconPath = getSpellOrItemIconPath(spell, isItem)

    // Normalize variants
    let extraMixins = {}
    maybeNormalizeSpellForEachVariants(spellModified)
    // Set spell props based on the current variant
    if (spellModified?.Variants?.length > 0) {
        const currentVariant = spellModified.Variants[variantIndex]
        if (currentVariant == null) {
            console.error(`ERROR: currentVariant is null. Printing below:`)
            console.log({spell, options, spellModified, variantIndex})
        }
        extraMixins = mapObject(currentVariant, ({key, value}) => ({
            key: key,
            value: { tag: 'span', text: value }
        }))
        if (spell.VariantStyle != null) {
            for (const [key, value] of Object.entries(extraMixins)) {
                if (!(key in spell.VariantStyle)) {
                    continue
                }
                const thisStyle = spell.VariantStyle[key]
                extraMixins[key] = {...value, props: { style: thisStyle }}
                console.log({extraMixins})
            }
        }
        spellModified.IconPath =
            currentVariant.IconName == null?
                spellModified.IconPath
            :isItem?
                getItemIconPathByName(currentVariant.IconName)
            :
                getSpellIconPathByName(currentVariant.IconName)
        spellModified.A = currentVariant.DisplayA ?? spell.A
        spellModified.SubspellName = currentVariant.SubspellName ?? spellModified.SubspellName
        spellModified.Cost = currentVariant.Cost ?? spellModified.Cost
        spellModified.TintColor = currentVariant.TintColor ?? spellModified.TintColor
        spellModified.Bonuses = currentVariant.Bonuses ?? spellModified.Bonuses
        spellModified['Skill Bonuses'] = currentVariant['Skill Bonuses'] ?? spellModified['Skill Bonuses']
    }

    // Parse all mixins, including variants
    if (spell.HasMixins === true || hasSpellVariants(spell)) {
        for (const propName of SPELL_PROPS_TO_PARSE) {
            if (spell[propName] == null) {
                continue
            }
            try {
                if (Array.isArray(spellModified[propName])) {
                    spellModified[propName] = spellModified[propName].map(text => parseTextWithSymbols(text, extraMixins))
                } else {
                    spellModified[propName] = parseTextWithSymbols(spell[propName], extraMixins)
                }
            } catch (e) {
                console.log({spell, options})
                throw `Error in Spell ${spellModified.Name} at prop ${propName} parsing text: ${spell[propName]}. Spell printed above. Error: ${e}`
            }
        }
        for (const propName of SPELL_PROPS_TO_PARSE_AS_TEXT) {
            if (spell[propName] == null) {
                continue
            }
            try {
                spellModified[propName] = parseTextWithSymbols(spell[propName], extraMixins, { shouldReturnStringsOnly: true})?.join('')
            } catch (e) {
                console.log({spell, options})
                throw `Error in Spell ${spellModified.Name} at prop as text ${propName} parsing text: ${spell[propName]}. Spell printed above. Error: ${e}`
            }
        }
        if (spell.CustomProps != null) {
            if (!isString(spell.CustomProps)) {
                console.error(`CustomProps given to spell printed above must be a JSON string!`)
            }
            try {
                const customPropsObj = JSON.parse(spell.CustomProps)
                const customPropsParsed = applyFuncToAllKeysAndValues(customPropsObj, (item, type) => {
                    if (item != null && isString(item)) {
                        return parseTextWithSymbols(item, extraMixins, { shouldReturnStringsOnly: true })?.join('')
                    }
                    return item
                })
                spellModified = {...spellModified, ...customPropsParsed}
            } catch (e) {
                throw e
            }
        }
        if (spellModified?.List?.length > 0) {
            const newList = []
            for (const li of spellModified.List) {
                const parsedLi = parseTextWithSymbols(li, extraMixins)
                newList.push(parsedLi)
            }
            spellModified.List = newList
        }
    }

    if (spellModified.DisplayName == null) {
        spellModified.DisplayName = spellModified.Name
    }

    let usedA = spellModified.DisplayA ?? spellModified.A
    if (isNumber(usedA)) {
        usedA = usedA == 1? '1 Action Point': `${usedA} Action Points`
    }
    spellModified.DisplayA = usedA

    spellModified.IsAlreadyParsed = true
    return spellModified
}
// Takes ForEachVariants and normalizes it into the .Variants property
export function maybeNormalizeSpellForEachVariants(spell) {
    if (spell.VariantsForEach == null) {
        return
    }
    spell.Variants = []
    for (let variant of spell.VariantsForEach) {
        const [mixinName, collectionName] = variant.ForEach.split(':')
        const collection = getVariantsForEachCollection(collectionName)
        const subvariants = collection.map(str => ({...variant, [mixinName]: str}))
        spell.Variants = [...spell.Variants, ...subvariants]  // TODO: This is incorrect!! If a spell will have multiple elements for VariantsForEach, it will not work properly!
    }
    delete spell.VariantsForEach
}
