export function smallestIndex(arr, func=elem=>elem) {
    if (arr == null || arr.length == 0) {
        return 0
    }
    let index = 0
    let smallestFound = func(arr[0])
    for (let i = 0; i < arr.length; i++) {
        const elem = arr[i]
        const value = func(elem)
        if (value < smallestFound) {
            smallestFound = value
            index = i
        }
    }
    return index
}
